-- ============================================================
-- SQL DUMP: BANK NASABAH DATABASE (CORE BANKING SIMULATION)
-- Database: bank_nasabah
-- Table: nasabah
-- ============================================================

CREATE DATABASE IF NOT EXISTS `bank_nasabah` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `bank_nasabah`;

DROP TABLE IF EXISTS `nasabah`;

CREATE TABLE `nasabah` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `cif` varchar(30) NOT NULL,
  `no_rekening` varchar(30) NOT NULL,
  `nama_nasabah` varchar(100) NOT NULL,
  `nik` varchar(20) NOT NULL,
  `no_telepon` varchar(25) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `alamat` text DEFAULT NULL,
  `cabang_pembuka` varchar(100) NOT NULL,
  `produk_rekening` varchar(50) NOT NULL,
  `segmentasi` varchar(50) NOT NULL,
  `saldo_terakhir` double NOT NULL DEFAULT 0,
  `status_kyc` varchar(30) NOT NULL DEFAULT 'Pending Review',
  `tanggal_buka_rekening` date DEFAULT NULL,
  `skor_risiko` varchar(30) DEFAULT 'Rendah',
  PRIMARY KEY (`id`),
  UNIQUE KEY `cif` (`cif`),
  UNIQUE KEY `no_rekening` (`no_rekening`),
  KEY `idx_cabang` (`cabang_pembuka`),
  KEY `idx_segmentasi` (`segmentasi`),
  KEY `idx_saldo` (`saldo_terakhir`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Data Records (500 Nasabah)
